"""Vietnamese text-to-SQL benchmark questions and executable gold SQL."""

CASES=[]

def add(level, question, sql, *tags):
    CASES.append({"difficulty":level,"question_vi":question,"gold_sql_sqlite":" ".join(sql.split()),"tags":list(tags)})

# 20 easy: one table, direct filter/projection/aggregate.
add("easy","Có bao nhiêu thuê bao trong bảng khách hàng?","SELECT COUNT(*) AS subscriber_count FROM customer__subscriber","count")
add("easy","Liệt kê mã và tên các tỉnh trong danh mục địa lý, sắp theo mã tỉnh.","SELECT province_code, province_name FROM geo__province ORDER BY province_code","projection")
add("easy","Đếm số trạm theo mã tỉnh, sắp theo số trạm giảm dần rồi mã tỉnh.","SELECT province_code, COUNT(*) AS station_count FROM inventory__station GROUP BY province_code ORDER BY station_count DESC, province_code","group")
add("easy","Đếm số cell 5G theo nhà cung cấp thiết bị.","SELECT vendor, COUNT(*) AS cell_count FROM ran__cell WHERE technology='5G' GROUP BY vendor ORDER BY vendor","filter","group")
add("easy","Liệt kê mã gói, tên gói và giá tháng, giá cao nhất trước.","SELECT plan_id, plan_name, monthly_fee_vnd FROM product__plan ORDER BY monthly_fee_vnd DESC, plan_id","projection")
add("easy","Có bao nhiêu hóa đơn tháng 2026-08 chưa thanh toán?","SELECT COUNT(*) AS unpaid_invoices FROM billing__invoice WHERE billing_month='2026-08' AND status='unpaid'","count","filter")
add("easy","Tính tổng tiền phải thu của hóa đơn tháng 2026-08.","SELECT SUM(total_vnd) AS total_due_vnd FROM billing__invoice WHERE billing_month='2026-08'","sum")
add("easy","Có bao nhiêu yêu cầu xác thực bị từ chối trong ba ngày dữ liệu?","SELECT COUNT(*) AS rejected_logins FROM aaa__authentication WHERE result='reject'","count","filter")
add("easy","Liệt kê thời điểm và điểm rủi ro của các sự kiện truy cập bị chặn.","SELECT event_time, risk_score FROM aaa__access_event WHERE result='blocked' ORDER BY event_time","projection","filter")
add("easy","Đếm số cell theo băng tần.","SELECT band, COUNT(*) AS cell_count FROM ran__cell GROUP BY band ORDER BY band","group")
add("easy","Tính tín hiệu Wi-Fi trung bình của tất cả bản ghi, làm tròn 2 chữ số.","SELECT ROUND(AVG(signal_dbm),2) AS avg_signal_dbm FROM acs__f_wifi","aggregate")
add("easy","Tìm số thiết bị khách Wi-Fi lớn nhất ghi nhận trong một bản ghi.","SELECT MAX(client_count) AS max_clients FROM acs__f_wifi","aggregate")
add("easy","Đếm cảnh báo theo mức độ nghiêm trọng.","SELECT severity, COUNT(*) AS alarm_count FROM fault__alarm GROUP BY severity ORDER BY severity","group")
add("easy","Liệt kê các nguyên nhân gốc khác nhau của cảnh báo.","SELECT DISTINCT root_cause FROM fault__alarm ORDER BY root_cause","distinct")
add("easy","Có bao nhiêu bản ghi năng lượng có mất điện trên 0 phút?","SELECT COUNT(*) AS outage_hours FROM energy__station_hourly WHERE power_outage_min>0","count","filter")
add("easy","Tổng giá trị KPI mẫu theo từng cấp vị trí là bao nhiêu?","SELECT location_level, SUM(kpi_value) AS total_kpi_value FROM aam__kpi_aam_daily_tdxl GROUP BY location_level ORDER BY location_level","group","source")
add("easy","Liệt kê 5 tỉnh có KPI mẫu bad_cell_throughput_5g cao nhất.","SELECT province_code, province_name, kpi_value FROM aam__kpi_aam_daily_tdxl WHERE location_level='province' AND kpi_code='bad_cell_throughput_5g' ORDER BY kpi_value DESC, province_code LIMIT 5","topk","source")
add("easy","Tổng lưu lượng tải xuống 5G trong ngày 2026-08-19 là bao nhiêu GB?","SELECT ROUND(SUM(dl_traffic_gb),2) AS dl_gb FROM ran_kpi__cell_hourly WHERE date_hour>='2026-08-19-00' AND date_hour<'2026-08-20-00'","sum","time")
add("easy","Có bao nhiêu ticket ưu tiên P1?","SELECT COUNT(*) AS p1_tickets FROM ops__ticket WHERE priority='P1'","count","filter")
add("easy","Đếm số lần kiểm tra ăng-ten đạt yêu cầu theo tỉnh.","SELECT province_code, COUNT(*) AS passed_inspections FROM maintenance__antenna_inspection WHERE inspection_result='pass' GROUP BY province_code ORDER BY province_code","group","maintenance")

# 20 medium: two-table joins, grouped business measures and limited conditional logic.
add("medium","Số thuê bao theo tên tỉnh là bao nhiêu?","SELECT g.province_name, COUNT(*) AS subscribers FROM customer__subscriber c JOIN geo__location g ON c.province_code=g.province_code GROUP BY g.province_name ORDER BY subscribers DESC,g.province_name","join","group")
add("medium","Mỗi gói cước có bao nhiêu tài khoản PPPoE?","SELECT p.plan_name, COUNT(*) AS accounts FROM aaa__ftth_account_pppoe a JOIN product__plan p ON a.plan_id=p.plan_id GROUP BY p.plan_id,p.plan_name ORDER BY accounts DESC,p.plan_name","join","group")
add("medium","Tổng tiền hóa đơn chưa thanh toán theo phân khúc khách hàng là bao nhiêu?","SELECT c.segment, SUM(i.total_vnd-i.paid_vnd) AS outstanding_vnd FROM billing__invoice i JOIN customer__subscriber c ON i.customer_id=c.customer_id WHERE i.status='unpaid' GROUP BY c.segment ORDER BY outstanding_vnd DESC,c.segment","join","sum")
add("medium","Đếm cell theo loại trạm lắp đặt.","SELECT s.station_type, COUNT(*) AS cells FROM ran__cell c JOIN inventory__station s ON c.station_id=s.station_id GROUP BY s.station_type ORDER BY cells DESC,s.station_type","join","group")
add("medium","Thông lượng tải xuống trung bình của cell theo loại trạm là bao nhiêu Mbps?","SELECT s.station_type, ROUND(AVG(k.dl_throughput_mbps),2) AS avg_dl_mbps FROM ran_kpi__cell_hourly k JOIN inventory__station s ON k.station_id=s.station_id GROUP BY s.station_type ORDER BY avg_dl_mbps DESC,s.station_type","join","aggregate")
add("medium","Tỷ lệ RRC thành công theo tên tỉnh trong ngày 2026-08-19 là bao nhiêu phần trăm?","SELECT g.province_name, ROUND(100.0*SUM(k.rrc_success)/NULLIF(SUM(k.rrc_attempt),0),2) AS rrc_success_pct FROM ran_kpi__cell_hourly k JOIN geo__location g ON k.province_code=g.province_code WHERE k.date_hour>='2026-08-19-00' AND k.date_hour<'2026-08-20-00' GROUP BY g.province_name ORDER BY g.province_name","join","ratio","time")
add("medium","Số client Wi-Fi trung bình theo nhà sản xuất thiết bị là bao nhiêu?","SELECT d.manufacturer, ROUND(AVG(w.client_count),2) AS avg_clients FROM acs__f_wifi w JOIN acs__device_info d ON w.device_id=d.device_id GROUP BY d.manufacturer ORDER BY d.manufacturer","join","aggregate")
add("medium","Thời gian uptime thấp nhất theo model thiết bị là bao nhiêu giây?","SELECT d.model, MIN(u.uptime_s) AS min_uptime_s FROM acs__f_uptime u JOIN acs__device_info d ON u.device_id=d.device_id GROUP BY d.model ORDER BY d.model","join","aggregate")
add("medium","Đếm cảnh báo theo loại trạm.","SELECT s.station_type, COUNT(*) AS alarms FROM fault__alarm a JOIN inventory__station s ON a.station_id=s.station_id GROUP BY s.station_type ORDER BY alarms DESC,s.station_type","join","group")
add("medium","Đếm ticket theo nguyên nhân cảnh báo và mức ưu tiên.","SELECT a.root_cause, t.priority, COUNT(*) AS ticket_count FROM ops__ticket t JOIN fault__alarm a ON t.alarm_id=a.alarm_id GROUP BY a.root_cause,t.priority ORDER BY a.root_cause,t.priority","join","group")
add("medium","Tổng số phút ngừng dịch vụ của work order theo loại trạm.","SELECT s.station_type, SUM(w.downtime_min) AS downtime_min FROM maintenance__work_order w JOIN inventory__station s ON w.station_id=s.station_id GROUP BY s.station_type ORDER BY downtime_min DESC,s.station_type","join","sum")
add("medium","Đếm đăng ký dịch vụ theo tên gói cước.","SELECT p.plan_name, COUNT(*) AS subscriptions FROM service__subscription s JOIN product__plan p ON s.plan_id=p.plan_id GROUP BY p.plan_id,p.plan_name ORDER BY subscriptions DESC,p.plan_name","join","group")
add("medium","Tỷ lệ tiền hóa đơn đã thu theo từng gói cước là bao nhiêu phần trăm?","SELECT p.plan_name, ROUND(100.0*SUM(i.paid_vnd)/NULLIF(SUM(i.total_vnd),0),2) AS collection_pct FROM billing__invoice i JOIN product__plan p ON i.plan_id=p.plan_id GROUP BY p.plan_id,p.plan_name ORDER BY collection_pct DESC,p.plan_name","join","ratio")
add("medium","Tổng chi phí điện theo tên tỉnh là bao nhiêu VND?","SELECT g.province_name, SUM(e.cost_vnd) AS energy_cost_vnd FROM energy__station_hourly e JOIN geo__location g ON e.province_code=g.province_code GROUP BY g.province_name ORDER BY energy_cost_vnd DESC,g.province_name","join","sum")
add("medium","Số giờ đường truyền có mức sử dụng trên 60 phần trăm theo loại trạm đầu tuyến.","SELECT s.station_type, COUNT(*) AS congested_link_hours FROM transport__link_hourly l JOIN inventory__station s ON l.from_station_id=s.station_id WHERE l.utilization_pct>60 GROUP BY s.station_type ORDER BY congested_link_hours DESC,s.station_type","join","filter")
add("medium","Trong sáu tỉnh có danh mục địa lý, tổng KPI mẫu của từng tỉnh là bao nhiêu?","SELECT g.province_name, SUM(a.kpi_value) AS bad_cells FROM aam__kpi_aam_daily_tdxl a JOIN geo__location g ON a.province_code=g.province_code WHERE a.location_level='province' GROUP BY g.province_name ORDER BY bad_cells DESC,g.province_name","join","source")
add("medium","Tỷ lệ yêu cầu QoS thành công theo tên gói cước là bao nhiêu phần trăm?","SELECT p.plan_name, ROUND(100.0*SUM(q.success_count)/NULLIF(SUM(q.request_count),0),2) AS success_pct FROM qos__service_hourly q JOIN product__plan p ON q.plan_id=p.plan_id GROUP BY p.plan_id,p.plan_name ORDER BY success_pct DESC,p.plan_name","join","ratio")
add("medium","Số dự báo rủi ro trung bình hoặc cao theo loại trạm.","SELECT s.station_type, COUNT(*) AS risky_forecasts FROM capacity__forecast_daily f JOIN inventory__station s ON f.station_id=s.station_id WHERE f.risk_level IN ('medium','high') GROUP BY s.station_type ORDER BY risky_forecasts DESC,s.station_type","join","filter")
add("medium","Số khiếu nại theo phân khúc thuê bao.","SELECT c.segment, COUNT(*) AS complaints FROM experience__complaint x JOIN customer__subscriber c ON x.customer_id=c.customer_id GROUP BY c.segment ORDER BY complaints DESC,c.segment","join","group")
add("medium","Liệt kê tên thay thế của vị trí theo tên tỉnh.","SELECT g.province_name, a.alias_name, a.normalized_name FROM geo__location_alias a JOIN geo__location g ON a.location_id=g.location_id ORDER BY g.province_name","join","geo")

# 30 hard: multi-schema joins, CTEs, window functions and anti joins.
add("hard","Trong ngày 2026-08-19, liệt kê 10 cell có tổng lưu lượng xuống cao nhất cùng tên tỉnh và trạm.","SELECT g.province_name,s.station_name,c.cell_id,ROUND(SUM(k.dl_traffic_gb),2) AS dl_gb FROM ran_kpi__cell_hourly k JOIN ran__cell c ON k.cell_id=c.cell_id JOIN inventory__station s ON c.station_id=s.station_id JOIN geo__location g ON s.location_id=g.location_id WHERE k.date_hour>='2026-08-19-00' AND k.date_hour<'2026-08-20-00' GROUP BY g.province_name,s.station_name,c.cell_id ORDER BY dl_gb DESC,c.cell_id LIMIT 10","multi_join","topk")
add("hard","Tỉnh nào có ít nhất hai giờ cell khả dụng dưới 99 phần trăm, kèm số giờ và mức khả dụng thấp nhất?","SELECT g.province_name,COUNT(*) AS degraded_cell_hours,MIN(k.availability_pct) AS min_availability_pct FROM ran_kpi__cell_hourly k JOIN geo__location g ON k.province_code=g.province_code WHERE k.availability_pct<99 GROUP BY g.province_name HAVING COUNT(*)>=2 ORDER BY degraded_cell_hours DESC,g.province_name","join","having")
add("hard","Mỗi cảnh báo gắn với bao nhiêu giờ cell của nó bị suy giảm trong khoảng cảnh báo đang mở?","SELECT a.alarm_id,a.root_cause,COUNT(k.cell_id) AS degraded_hours FROM fault__alarm a LEFT JOIN ran_kpi__cell_hourly k ON a.entity_id=k.cell_id AND k.date_hour>=REPLACE(SUBSTR(a.opened_at,1,13),' ','-') AND k.date_hour<REPLACE(SUBSTR(a.closed_at,1,13),' ','-') AND k.kpi_quality_flag='degraded' GROUP BY a.alarm_id,a.root_cause ORDER BY a.alarm_id","temporal_join","alarm")
add("hard","Liệt kê các trạm chưa từng có cảnh báo, kèm tên tỉnh và số cell.","SELECT s.station_id,g.province_name,COUNT(c.cell_id) AS cells FROM inventory__station s JOIN geo__location g ON s.location_id=g.location_id LEFT JOIN ran__cell c ON c.station_id=s.station_id WHERE NOT EXISTS (SELECT 1 FROM fault__alarm a WHERE a.station_id=s.station_id) GROUP BY s.station_id,g.province_name ORDER BY s.station_id","anti_join","multi_join")
add("hard","Khách hàng nào vừa có hóa đơn chưa thanh toán vừa có khiếu nại, và số tiền còn nợ là bao nhiêu?","SELECT c.customer_id,g.province_name,SUM(i.total_vnd-i.paid_vnd) AS outstanding_vnd,COUNT(DISTINCT x.complaint_id) AS complaints FROM customer__subscriber c JOIN billing__invoice i ON c.customer_id=i.customer_id JOIN experience__complaint x ON c.customer_id=x.customer_id JOIN geo__location g ON c.province_code=g.province_code WHERE i.status='unpaid' GROUP BY c.customer_id,g.province_name ORDER BY outstanding_vnd DESC,c.customer_id","multi_join","intersection")
add("hard","Số lần xác thực bị từ chối theo vùng và gói cước là bao nhiêu?","SELECT g.area_code,p.plan_name,COUNT(*) AS rejects FROM aaa__authentication h JOIN aaa__ftth_account_pppoe a ON h.account_id=a.account_id JOIN product__plan p ON a.plan_id=p.plan_id JOIN geo__location g ON a.province_code=g.province_code WHERE h.result='reject' GROUP BY g.area_code,p.plan_name ORDER BY rejects DESC,g.area_code,p.plan_name","multi_join","group")
add("hard","Tính tỷ lệ xác thực thành công tạo được phiên accounting theo tỉnh.","SELECT g.province_name,SUM(CASE WHEN h.result='accept' THEN 1 ELSE 0 END) AS accepted_logins,SUM(CASE WHEN h.result='accept' AND x.session_id IS NOT NULL THEN 1 ELSE 0 END) AS recorded_sessions,ROUND(100.0*SUM(CASE WHEN h.result='accept' AND x.session_id IS NOT NULL THEN 1 ELSE 0 END)/NULLIF(SUM(CASE WHEN h.result='accept' THEN 1 ELSE 0 END),0),2) AS accounting_pct FROM aaa__authentication h JOIN geo__location g ON h.province_code=g.province_code LEFT JOIN aaa__accounting x ON h.session_id=x.session_id GROUP BY g.province_name ORDER BY g.province_name","left_join","ratio")
add("hard","Ngày nào có lưu lượng tải xuống 5G cao nhất của từng tỉnh?","WITH d AS (SELECT province_code,SUBSTR(date_hour,1,10) AS day,SUM(dl_traffic_gb) AS gb FROM ran_kpi__cell_hourly GROUP BY province_code,SUBSTR(date_hour,1,10)),r AS (SELECT province_code,day,ROUND(gb,2) AS gb,ROW_NUMBER() OVER(PARTITION BY province_code ORDER BY gb DESC,day) AS rn FROM d) SELECT province_code,day,gb FROM r WHERE rn=1 ORDER BY province_code","cte","window")
add("hard","Ngày 2026-08-19, những cell nào có thông lượng tải xuống trung bình thấp hơn trung bình tỉnh của chính chúng? Chỉ lấy 20 cell thấp nhất.","WITH c AS (SELECT cell_id,province_code,AVG(dl_throughput_mbps) AS avg_dl FROM ran_kpi__cell_hourly WHERE date_hour>='2026-08-19-00' AND date_hour<'2026-08-20-00' GROUP BY cell_id,province_code),p AS (SELECT province_code,AVG(avg_dl) AS province_avg FROM c GROUP BY province_code) SELECT c.province_code,c.cell_id,ROUND(c.avg_dl,2) AS cell_mbps,ROUND(p.province_avg,2) AS province_mbps FROM c JOIN p ON c.province_code=p.province_code WHERE c.avg_dl<p.province_avg ORDER BY c.avg_dl,c.cell_id LIMIT 20","cte","benchmark_ratio")
add("hard","Tính tỷ số lưu lượng 5G giờ cao điểm 18-22 so với giờ thấp điểm 00-06 theo tỉnh.","SELECT province_code,ROUND(SUM(CASE WHEN CAST(SUBSTR(date_hour,12,2) AS INTEGER) BETWEEN 18 AND 22 THEN dl_traffic_gb ELSE 0 END)/NULLIF(SUM(CASE WHEN CAST(SUBSTR(date_hour,12,2) AS INTEGER) BETWEEN 0 AND 6 THEN dl_traffic_gb ELSE 0 END),0),2) AS peak_to_offpeak FROM ran_kpi__cell_hourly GROUP BY province_code ORDER BY peak_to_offpeak DESC,province_code","conditional_agg","time")
add("hard","Những giờ nào vừa mất điện tại trạm vừa có đường truyền đầu trạm bị suy giảm?","SELECT e.station_id,e.date_hour,e.power_outage_min,l.link_id,l.packet_loss_pct FROM energy__station_hourly e JOIN transport__link_hourly l ON e.station_id=l.from_station_id AND e.date_hour=l.date_hour WHERE e.power_outage_min>0 AND l.status='degraded' ORDER BY e.date_hour,e.station_id","temporal_join","incident")
add("hard","Liệt kê 10 tỉnh-giờ có chênh lệch lớn nhất giữa tỷ lệ attach lõi và tỷ lệ thành công QoS.","SELECT c.province_code,c.date_hour,ROUND(100.0*c.attach_success/NULLIF(c.attach_attempt,0),2) AS attach_pct,ROUND(100.0*q.success_count/NULLIF(q.request_count,0),2) AS qos_pct,ROUND(ABS(100.0*c.attach_success/NULLIF(c.attach_attempt,0)-100.0*q.success_count/NULLIF(q.request_count,0)),2) AS gap_pct FROM core__gateway_hourly c JOIN qos__service_hourly q ON c.province_code=q.province_code AND c.date_hour=q.date_hour ORDER BY gap_pct DESC,c.province_code,c.date_hour LIMIT 10","temporal_join","ratio")
add("hard","Đếm số lần uptime thiết bị giảm so với bản ghi trước, theo tỉnh.","WITH u AS (SELECT d.province_code,f.device_id,f.record_time,f.uptime_s,LAG(f.uptime_s) OVER(PARTITION BY f.device_id ORDER BY f.record_time) AS prev_uptime FROM acs__f_uptime f JOIN acs__device_info d ON f.device_id=d.device_id) SELECT g.province_code,COUNT(u.device_id) AS resets FROM geo__province g LEFT JOIN u ON g.province_code=u.province_code AND u.prev_uptime IS NOT NULL AND u.uptime_s<u.prev_uptime GROUP BY g.province_code ORDER BY g.province_code","window","device")
add("hard","Liệt kê 10 bản ghi Wi-Fi có tỷ lệ retry cao hơn trung bình tỉnh của thiết bị.","WITH p AS (SELECT province_code,AVG(retry_rate) AS avg_retry FROM acs__f_wifi GROUP BY province_code) SELECT d.device_id,d.province_code,w.date_hour,ROUND(w.retry_rate,4) AS retry_rate,ROUND(p.avg_retry,4) AS province_avg FROM acs__f_wifi w JOIN acs__device_info d ON w.device_id=d.device_id JOIN p ON d.province_code=p.province_code WHERE w.retry_rate>p.avg_retry ORDER BY w.retry_rate DESC,d.device_id,w.date_hour LIMIT 10","cte","wifi")
add("hard","Theo tỉnh, so tổng hóa đơn phát hành ngày 2026-08-20 với tổng chi phí đã phân bổ ngày đó; tính chênh lệch.","WITH rev AS (SELECT province_code,SUM(total_vnd) AS billed FROM billing__invoice WHERE issued_date='2026-08-20' GROUP BY province_code),cost AS (SELECT province_code,SUM(total_cost_vnd) AS spent FROM billing__cost_center_daily WHERE cost_date='2026-08-20' GROUP BY province_code) SELECT g.province_name,rev.billed,cost.spent,rev.billed-cost.spent AS gross_gap_vnd FROM rev JOIN cost ON rev.province_code=cost.province_code JOIN geo__location g ON rev.province_code=g.province_code ORDER BY gross_gap_vnd DESC,g.province_name","multi_cte","finance")
add("hard","Tổng nợ chưa thanh toán theo phân khúc khách hàng và tên gói là bao nhiêu?","SELECT c.segment,p.plan_name,SUM(i.total_vnd-i.paid_vnd) AS outstanding_vnd FROM billing__invoice i JOIN customer__subscriber c ON i.customer_id=c.customer_id JOIN product__plan p ON i.plan_id=p.plan_id WHERE i.paid_vnd<i.total_vnd GROUP BY c.segment,p.plan_name ORDER BY outstanding_vnd DESC,c.segment,p.plan_name","multi_join","finance")
add("hard","Xếp hạng gói cước theo doanh thu hóa đơn và cho biết số thuê bao mỗi gói.","WITH r AS (SELECT p.plan_id,p.plan_name,COUNT(DISTINCT s.customer_id) AS subscribers,SUM(i.total_vnd) AS billed_vnd FROM product__plan p JOIN service__subscription s ON p.plan_id=s.plan_id JOIN billing__invoice i ON s.customer_id=i.customer_id AND s.plan_id=i.plan_id GROUP BY p.plan_id,p.plan_name) SELECT plan_name,subscribers,billed_vnd,DENSE_RANK() OVER(ORDER BY billed_vnd DESC) AS revenue_rank FROM r ORDER BY revenue_rank,plan_name","cte","window","revenue")
add("hard","Với mỗi nguyên nhân cảnh báo, có bao nhiêu ticket được xử lý trước hạn SLA?","SELECT a.root_cause,COUNT(*) AS tickets,SUM(CASE WHEN t.resolved_at<=t.sla_deadline THEN 1 ELSE 0 END) AS within_sla FROM ops__ticket t JOIN fault__alarm a ON t.alarm_id=a.alarm_id GROUP BY a.root_cause ORDER BY a.root_cause","join","sla")
add("hard","Theo tỉnh, tổng quãng đường kỹ thuật viên di chuyển và tổng số người bị tác động của cảnh báo liên quan là bao nhiêu?","SELECT g.province_name,ROUND(SUM(v.travel_km),2) AS travel_km,SUM(a.impact_users) AS impact_users FROM ops__technician_visit v JOIN ops__ticket t ON v.ticket_id=t.ticket_id JOIN fault__alarm a ON t.alarm_id=a.alarm_id JOIN geo__location g ON a.province_code=g.province_code GROUP BY g.province_name ORDER BY impact_users DESC,g.province_name","multi_join","incident")
add("hard","Liệt kê khiếu nại được mở trong thời gian cảnh báo của chính ticket đó đang hoạt động.","SELECT x.complaint_id,a.alarm_id,x.opened_at,a.opened_at,a.closed_at FROM experience__complaint x JOIN ops__ticket t ON x.ticket_id=t.ticket_id JOIN fault__alarm a ON t.alarm_id=a.alarm_id WHERE x.opened_at>=a.opened_at AND x.opened_at<=a.closed_at ORDER BY x.complaint_id","temporal_join","complaint")
add("hard","Đếm giờ cell khả dụng dưới 99 phần trăm nhưng không có cảnh báo đang mở cho cell đó.","SELECT COUNT(*) AS unalarmed_degraded_hours FROM ran_kpi__cell_hourly k WHERE k.availability_pct<99 AND NOT EXISTS (SELECT 1 FROM fault__alarm a WHERE a.entity_id=k.cell_id AND k.date_hour>=REPLACE(SUBSTR(a.opened_at,1,13),' ','-') AND k.date_hour<REPLACE(SUBSTR(a.closed_at,1,13),' ','-'))","anti_join","quality")
add("hard","Theo gói cước, đếm đăng ký có phí tháng đúng giá trong danh mục gói.","SELECT p.plan_name,COUNT(*) AS matched_subscriptions FROM service__subscription s JOIN product__plan p ON s.plan_id=p.plan_id WHERE s.monthly_fee_vnd=p.monthly_fee_vnd GROUP BY p.plan_name ORDER BY matched_subscriptions DESC,p.plan_name","join","quality")
add("hard","Liệt kê khách hàng có khiếu nại và còn nợ, kèm tên tỉnh, số khiếu nại và tiền nợ.","WITH debt AS (SELECT customer_id,SUM(total_vnd-paid_vnd) AS debt_vnd FROM billing__invoice GROUP BY customer_id HAVING SUM(total_vnd-paid_vnd)>0),complaints AS (SELECT customer_id,COUNT(*) AS n FROM experience__complaint GROUP BY customer_id) SELECT c.customer_id,g.province_name,complaints.n,debt.debt_vnd FROM debt JOIN complaints ON debt.customer_id=complaints.customer_id JOIN customer__subscriber c ON debt.customer_id=c.customer_id JOIN geo__location g ON c.province_code=g.province_code ORDER BY debt.debt_vnd DESC,c.customer_id","multi_cte","intersection")
add("hard","Tìm trạm tốn điện nhiều nhất ở từng tỉnh trong ba ngày và số kWh lưới của trạm.","WITH e AS (SELECT station_id,province_code,SUM(cost_vnd) AS cost_vnd,ROUND(SUM(grid_kwh),2) AS grid_kwh FROM energy__station_hourly GROUP BY station_id,province_code),r AS (SELECT e.*,ROW_NUMBER() OVER(PARTITION BY province_code ORDER BY cost_vnd DESC,station_id) AS rn FROM e) SELECT province_code,station_id,cost_vnd,grid_kwh FROM r WHERE rn=1 ORDER BY province_code","cte","window","energy")
add("hard","So dự báo lưu lượng ngày 2026-08-21 với lưu lượng cell thực tế ngày 2026-08-20 theo trạm.","WITH actual AS (SELECT station_id,ROUND(SUM(dl_traffic_gb+ul_traffic_gb),2) AS actual_gb FROM ran_kpi__cell_hourly WHERE date_hour>='2026-08-20-00' AND date_hour<'2026-08-21-00' GROUP BY station_id) SELECT f.station_id,f.province_code,f.forecast_traffic_gb,a.actual_gb,ROUND(f.forecast_traffic_gb-a.actual_gb,2) AS forecast_gap_gb FROM capacity__forecast_daily f JOIN actual a ON f.station_id=a.station_id WHERE f.forecast_date='2026-08-21' ORDER BY ABS(f.forecast_traffic_gb-a.actual_gb) DESC,f.station_id","cte","forecast")
add("hard","So KPI nguồn bad_cell_throughput_5g theo tỉnh với số giờ cell suy giảm tổng hợp trong ba ngày.","WITH src AS (SELECT province_code,SUM(kpi_value) AS source_bad_cells FROM aam__kpi_aam_daily_tdxl WHERE location_level='province' GROUP BY province_code),deg AS (SELECT province_code,COUNT(*) AS degraded_hours FROM ran_kpi__cell_hourly WHERE kpi_quality_flag='degraded' GROUP BY province_code) SELECT src.province_code,src.source_bad_cells,COALESCE(deg.degraded_hours,0) AS synthetic_degraded_hours FROM src LEFT JOIN deg ON src.province_code=deg.province_code WHERE src.province_code IN (SELECT province_code FROM geo__location) ORDER BY src.province_code","multi_cte","source","comparison")
add("hard","Theo trạm và ngày, so retry Wi-Fi trung bình với khả dụng cell thấp nhất tại cùng trạm.","WITH wifi AS (SELECT d.station_id,SUBSTR(w.date_hour,1,10) AS day,AVG(w.retry_rate) AS avg_retry FROM acs__f_wifi w JOIN acs__device_info d ON w.device_id=d.device_id GROUP BY d.station_id,SUBSTR(w.date_hour,1,10)),cell AS (SELECT station_id,SUBSTR(date_hour,1,10) AS day,MIN(availability_pct) AS min_availability FROM ran_kpi__cell_hourly GROUP BY station_id,SUBSTR(date_hour,1,10)) SELECT wifi.station_id,wifi.day,ROUND(wifi.avg_retry,4) AS avg_retry,cell.min_availability FROM wifi JOIN cell ON wifi.station_id=cell.station_id AND wifi.day=cell.day ORDER BY cell.min_availability,wifi.station_id,wifi.day LIMIT 15","multi_cte","device","ran")
add("hard","Liệt kê 10 tỉnh-giờ có tổng request lõi và QoS lớn nhất, kèm tỷ lệ thành công của từng hệ.","SELECT c.province_code,c.date_hour,c.attach_attempt+q.request_count AS total_requests,ROUND(100.0*c.attach_success/NULLIF(c.attach_attempt,0),2) AS core_pct,ROUND(100.0*q.success_count/NULLIF(q.request_count,0),2) AS qos_pct FROM core__gateway_hourly c JOIN qos__service_hourly q ON c.province_code=q.province_code AND c.date_hour=q.date_hour ORDER BY total_requests DESC,c.province_code,c.date_hour LIMIT 10","temporal_join","ratio")
add("hard","Theo tỉnh, so dân số huyện giả lập với số trạm và số cell đang hoạt động.","WITH infra AS (SELECT g.province_code,COUNT(DISTINCT s.station_id) AS stations,COUNT(c.cell_id) AS cells FROM geo__location g JOIN inventory__station s ON g.location_id=s.location_id JOIN ran__cell c ON s.station_id=c.station_id GROUP BY g.province_code) SELECT p.province_name,d.population_count,infra.stations,infra.cells FROM geo__district_population_daily d JOIN geo__province p ON d.province_code=p.province_code JOIN infra ON d.province_code=infra.province_code WHERE d.date_hour='2026-08-20-00' ORDER BY d.population_count DESC,p.province_name","multi_join","geo")
add("hard","Có bao nhiêu bản ghi g_uptime không khớp uptime và uptime_delta của f_uptime theo thiết bị-giờ?","SELECT COUNT(*) AS mismatched_rollups FROM acs__g_uptime g LEFT JOIN acs__f_uptime f ON g.ne_id=f.ne_id AND g.date_hour=f.date_hour WHERE f.ne_id IS NULL OR CAST(g.uptime AS INTEGER)<>f.uptime_s OR CAST(g.uptime_delta AS INTEGER)<>f.uptime_delta_s","join","quality","source")

# 30 extreme: multi-stage reasoning, incident timelines, windows and composite metrics.
add("extreme","Mỗi tỉnh lấy cell có khả dụng trung bình thấp nhất trong ngày 2026-08-19, kèm số giờ suy giảm và tên trạm.","WITH x AS (SELECT cell_id,station_id,province_code,ROUND(AVG(availability_pct),2) AS avg_availability,SUM(CASE WHEN kpi_quality_flag='degraded' THEN 1 ELSE 0 END) AS degraded_hours FROM ran_kpi__cell_hourly WHERE date_hour>='2026-08-19-00' AND date_hour<'2026-08-20-00' GROUP BY cell_id,station_id,province_code),r AS (SELECT x.*,ROW_NUMBER() OVER(PARTITION BY province_code ORDER BY avg_availability,cell_id) AS rn FROM x) SELECT g.province_name,s.station_name,r.cell_id,r.avg_availability,r.degraded_hours FROM r JOIN inventory__station s ON r.station_id=s.station_id JOIN geo__location g ON r.province_code=g.province_code WHERE r.rn=1 ORDER BY g.province_name","multi_cte","window","ran")
add("extreme","Tìm các chuỗi suy giảm cell liên tiếp dài ít nhất hai giờ và ghép nguyên nhân cảnh báo của cell.","WITH x AS (SELECT cell_id,date_hour,kpi_quality_flag,LAG(kpi_quality_flag) OVER(PARTITION BY cell_id ORDER BY date_hour) AS prev_flag FROM ran_kpi__cell_hourly),y AS (SELECT cell_id,date_hour,kpi_quality_flag,SUM(CASE WHEN kpi_quality_flag='degraded' AND COALESCE(prev_flag,'normal')<>'degraded' THEN 1 ELSE 0 END) OVER(PARTITION BY cell_id ORDER BY date_hour) AS run_no FROM x),runs AS (SELECT cell_id,run_no,MIN(date_hour) AS start_hour,MAX(date_hour) AS end_hour,COUNT(*) AS hours FROM y WHERE kpi_quality_flag='degraded' GROUP BY cell_id,run_no HAVING COUNT(*)>=2) SELECT r.cell_id,r.start_hour,r.end_hour,r.hours,a.root_cause FROM runs r JOIN fault__alarm a ON r.cell_id=a.entity_id ORDER BY r.hours DESC,r.cell_id","multi_cte","window","incident")
add("extreme","Liệt kê 15 giờ cell có lưu lượng tải xuống giảm mạnh nhất so với giờ trước, kèm tên tỉnh và phần trăm giảm.","WITH x AS (SELECT cell_id,station_id,province_code,date_hour,dl_traffic_gb,LAG(dl_traffic_gb) OVER(PARTITION BY cell_id ORDER BY date_hour) AS prev_gb FROM ran_kpi__cell_hourly) SELECT g.province_name,s.station_name,x.cell_id,x.date_hour,ROUND(100.0*(x.prev_gb-x.dl_traffic_gb)/NULLIF(x.prev_gb,0),2) AS drop_pct FROM x JOIN inventory__station s ON x.station_id=s.station_id JOIN geo__location g ON x.province_code=g.province_code WHERE x.prev_gb>0 AND x.dl_traffic_gb<x.prev_gb ORDER BY drop_pct DESC,x.cell_id,x.date_hour LIMIT 15","window","multi_join","anomaly")
add("extreme","Ước lượng p95 độ trễ cell theo tỉnh bằng thứ hạng quan sát trong ba ngày.","WITH r AS (SELECT province_code,latency_ms,ROW_NUMBER() OVER(PARTITION BY province_code ORDER BY latency_ms) AS rn,COUNT(*) OVER(PARTITION BY province_code) AS n FROM ran_kpi__cell_hourly),p AS (SELECT province_code,MIN(latency_ms) AS p95_latency_ms FROM r WHERE rn>=0.95*n GROUP BY province_code) SELECT g.province_name,ROUND(p.p95_latency_ms,2) AS p95_latency_ms FROM p JOIN geo__location g ON p.province_code=g.province_code ORDER BY p95_latency_ms DESC,g.province_name","window","percentile","geo")
add("extreme","Trong 10 phần trăm giờ sử dụng PRB tải xuống cao nhất từng tỉnh, thông lượng và độ trễ trung bình là bao nhiêu?","WITH r AS (SELECT province_code,prb_dl_util_pct,dl_throughput_mbps,latency_ms,NTILE(10) OVER(PARTITION BY province_code ORDER BY prb_dl_util_pct DESC) AS decile FROM ran_kpi__cell_hourly) SELECT province_code,COUNT(*) AS busy_hours,ROUND(AVG(prb_dl_util_pct),2) AS avg_prb_pct,ROUND(AVG(dl_throughput_mbps),2) AS avg_dl_mbps,ROUND(AVG(latency_ms),2) AS avg_latency_ms FROM r WHERE decile=1 GROUP BY province_code ORDER BY avg_prb_pct DESC,province_code","window","ran","qos")
add("extreme","Các cell nào có tỷ lệ handover thấp hơn trung bình các cell trong tỉnh của nó, chỉ lấy 15 cell thấp nhất?","WITH c AS (SELECT cell_id,province_code,100.0*SUM(ho_success)/NULLIF(SUM(ho_attempt),0) AS ho_pct FROM ran_kpi__cell_hourly GROUP BY cell_id,province_code),p AS (SELECT province_code,AVG(ho_pct) AS province_ho_pct FROM c GROUP BY province_code) SELECT c.province_code,c.cell_id,ROUND(c.ho_pct,2) AS cell_ho_pct,ROUND(p.province_ho_pct,2) AS province_ho_pct FROM c JOIN p ON c.province_code=p.province_code WHERE c.ho_pct<p.province_ho_pct ORDER BY c.ho_pct,c.cell_id LIMIT 15","multi_cte","ratio","anomaly")
add("extreme","Tìm tài khoản có ít nhất ba lần xác thực bị từ chối liên tiếp, kèm thời điểm lần từ chối thứ ba và tỉnh.","WITH x AS (SELECT account_id,province_code,event_time,result,LAG(result,1) OVER(PARTITION BY account_id ORDER BY event_time) AS prev1,LAG(result,2) OVER(PARTITION BY account_id ORDER BY event_time) AS prev2 FROM aaa__authentication) SELECT x.account_id,g.province_name,x.event_time AS third_reject_at FROM x JOIN geo__location g ON x.province_code=g.province_code WHERE x.result='reject' AND x.prev1='reject' AND x.prev2='reject' ORDER BY x.account_id,x.event_time","window","security","multi_join")
add("extreme","Xếp hạng ba thuê bao có tổng download phiên PPPoE cao nhất trong từng tỉnh, kèm gói cước.","WITH d AS (SELECT a.customer_id,a.province_code,a.plan_id,ROUND(SUM(x.download_mb),2) AS download_mb FROM aaa__accounting x JOIN aaa__ftth_account_pppoe a ON x.account_id=a.account_id GROUP BY a.customer_id,a.province_code,a.plan_id),r AS (SELECT d.*,ROW_NUMBER() OVER(PARTITION BY province_code ORDER BY download_mb DESC,customer_id) AS rn FROM d) SELECT g.province_name,r.customer_id,p.plan_name,r.download_mb,r.rn FROM r JOIN product__plan p ON r.plan_id=p.plan_id JOIN geo__location g ON r.province_code=g.province_code WHERE r.rn<=3 ORDER BY g.province_name,r.rn","multi_cte","window","aaa")
add("extreme","Khách hàng nào đồng thời có đăng nhập bị chặn, hóa đơn còn nợ và khiếu nại?","WITH blocked AS (SELECT DISTINCT customer_id FROM aaa__access_event WHERE result='blocked'),debt AS (SELECT customer_id,SUM(total_vnd-paid_vnd) AS debt_vnd FROM billing__invoice GROUP BY customer_id HAVING SUM(total_vnd-paid_vnd)>0),complaints AS (SELECT customer_id,COUNT(*) AS complaint_count FROM experience__complaint GROUP BY customer_id) SELECT c.customer_id,c.province_code,debt.debt_vnd,complaints.complaint_count FROM customer__subscriber c JOIN blocked ON c.customer_id=blocked.customer_id JOIN debt ON c.customer_id=debt.customer_id JOIN complaints ON c.customer_id=complaints.customer_id ORDER BY debt.debt_vnd DESC,c.customer_id","multi_cte","security","intersection")
add("extreme","Liệt kê hóa đơn có tỷ lệ thu thấp hơn trung bình tỉnh, kèm thứ hạng nợ trong tỉnh.","WITH x AS (SELECT invoice_id,customer_id,province_code,total_vnd,paid_vnd,100.0*paid_vnd/NULLIF(total_vnd,0) AS paid_pct FROM billing__invoice),r AS (SELECT x.*,AVG(paid_pct) OVER(PARTITION BY province_code) AS province_avg,DENSE_RANK() OVER(PARTITION BY province_code ORDER BY total_vnd-paid_vnd DESC) AS debt_rank FROM x) SELECT province_code,invoice_id,customer_id,ROUND(paid_pct,2) AS paid_pct,ROUND(province_avg,2) AS province_avg,debt_rank FROM r WHERE paid_pct<province_avg ORDER BY province_code,debt_rank,invoice_id","cte","window","finance")
add("extreme","Tính doanh thu hóa đơn trên mỗi thuê bao theo vùng và phân khúc, rồi xếp hạng phân khúc trong từng vùng.","WITH x AS (SELECT c.area_code,c.segment,COUNT(DISTINCT c.customer_id) AS subscribers,SUM(i.total_vnd) AS billed_vnd FROM customer__subscriber c JOIN billing__invoice i ON c.customer_id=i.customer_id GROUP BY c.area_code,c.segment),r AS (SELECT x.*,ROUND(1.0*billed_vnd/NULLIF(subscribers,0),2) AS billed_per_subscriber,DENSE_RANK() OVER(PARTITION BY area_code ORDER BY 1.0*billed_vnd/NULLIF(subscribers,0) DESC) AS rn FROM x) SELECT area_code,segment,subscribers,billed_vnd,billed_per_subscriber,rn FROM r ORDER BY area_code,rn,segment","cte","window","finance")
add("extreme","Theo gói cước, tính tỷ lệ khách hàng có khiếu nại và tỷ lệ hóa đơn chưa thanh toán mà không nhân bản lượt join.","WITH subscribers AS (SELECT plan_id,COUNT(*) AS n FROM service__subscription GROUP BY plan_id),complainers AS (SELECT s.plan_id,COUNT(DISTINCT s.customer_id) AS n FROM service__subscription s JOIN experience__complaint c ON s.customer_id=c.customer_id GROUP BY s.plan_id),unpaid AS (SELECT plan_id,COUNT(*) AS n FROM billing__invoice WHERE paid_vnd<total_vnd GROUP BY plan_id) SELECT p.plan_name,subscribers.n AS subscribers,ROUND(100.0*COALESCE(complainers.n,0)/NULLIF(subscribers.n,0),2) AS complaint_pct,ROUND(100.0*COALESCE(unpaid.n,0)/NULLIF(subscribers.n,0),2) AS unpaid_pct FROM product__plan p JOIN subscribers ON p.plan_id=subscribers.plan_id LEFT JOIN complainers ON p.plan_id=complainers.plan_id LEFT JOIN unpaid ON p.plan_id=unpaid.plan_id ORDER BY complaint_pct DESC,p.plan_name","multi_cte","ratio","customer")
add("extreme","Hiển thị tuyến xử lý đầy đủ của từng sự cố: cảnh báo, nhận ticket, bắt đầu công việc, kỹ thuật viên đến, đóng cảnh báo; đánh dấu thứ tự thời gian hợp lệ.","SELECT a.alarm_id,a.root_cause,a.opened_at,t.acknowledged_at,w.actual_start,v.arrived_at,a.closed_at,CASE WHEN a.opened_at<=t.acknowledged_at AND t.acknowledged_at<=w.actual_start AND w.actual_start<=v.arrived_at AND v.arrived_at<=a.closed_at THEN 1 ELSE 0 END AS valid_sequence FROM fault__alarm a JOIN ops__ticket t ON a.ticket_id=t.ticket_id JOIN maintenance__work_order w ON t.ticket_id=w.ticket_id JOIN ops__technician_visit v ON w.work_order_id=v.work_order_id ORDER BY a.alarm_id","multi_join","timeline","quality")
add("extreme","Theo nguyên nhân sự cố, tính tỷ lệ ticket đạt SLA và tổng người dùng bị tác động.","WITH x AS (SELECT a.root_cause,a.impact_users,CASE WHEN t.resolved_at<=t.sla_deadline THEN 1 ELSE 0 END AS within_sla FROM fault__alarm a JOIN ops__ticket t ON a.ticket_id=t.ticket_id) SELECT root_cause,COUNT(*) AS tickets,SUM(impact_users) AS impacted_users,ROUND(100.0*SUM(within_sla)/NULLIF(COUNT(*),0),2) AS sla_pct FROM x GROUP BY root_cause ORDER BY impacted_users DESC,root_cause","cte","sla","impact")
add("extreme","Với từng cảnh báo, so giờ cell đầu tiên bị suy giảm với giờ cảnh báo mở và đếm giờ suy giảm trước cảnh báo.","WITH d AS (SELECT a.alarm_id,a.entity_id,MIN(k.date_hour) AS first_degraded_hour,SUM(CASE WHEN k.date_hour<REPLACE(SUBSTR(a.opened_at,1,13),' ','-') THEN 1 ELSE 0 END) AS hours_before_alarm FROM fault__alarm a JOIN ran_kpi__cell_hourly k ON a.entity_id=k.cell_id AND k.kpi_quality_flag='degraded' GROUP BY a.alarm_id,a.entity_id) SELECT a.alarm_id,d.first_degraded_hour,REPLACE(SUBSTR(a.opened_at,1,13),' ','-') AS alarm_hour,d.hours_before_alarm FROM d JOIN fault__alarm a ON d.alarm_id=a.alarm_id ORDER BY a.alarm_id","temporal_join","incident","quality")
add("extreme","Xếp hạng trạm theo số giờ đồng thời có cell suy giảm, mất điện và đường truyền kém khả dụng.","WITH r AS (SELECT station_id,date_hour,COUNT(*) AS bad_cells FROM ran_kpi__cell_hourly WHERE kpi_quality_flag='degraded' GROUP BY station_id,date_hour),e AS (SELECT station_id,date_hour,SUM(power_outage_min) AS outage_min FROM energy__station_hourly GROUP BY station_id,date_hour),t AS (SELECT from_station_id AS station_id,date_hour,MIN(availability_pct) AS min_link_avail FROM transport__link_hourly GROUP BY from_station_id,date_hour) SELECT r.station_id,COUNT(*) AS simultaneous_hours,SUM(r.bad_cells) AS bad_cell_hours,SUM(e.outage_min) AS outage_min FROM r JOIN e ON r.station_id=e.station_id AND r.date_hour=e.date_hour JOIN t ON r.station_id=t.station_id AND r.date_hour=t.date_hour WHERE e.outage_min>0 AND t.min_link_avail<99 GROUP BY r.station_id ORDER BY simultaneous_hours DESC,r.station_id","multi_cte","correlation","network")
add("extreme","Với mỗi cảnh báo, kiểm tra tại giờ mở có mất điện hoặc suy giảm đường truyền ở trạm tương ứng.","WITH e AS (SELECT station_id,date_hour,SUM(power_outage_min) AS outage_min FROM energy__station_hourly GROUP BY station_id,date_hour),t AS (SELECT from_station_id AS station_id,date_hour,MIN(availability_pct) AS min_link_avail FROM transport__link_hourly GROUP BY from_station_id,date_hour) SELECT a.alarm_id,a.root_cause,COALESCE(e.outage_min,0) AS outage_min,t.min_link_avail,CASE WHEN COALESCE(e.outage_min,0)>0 THEN 1 ELSE 0 END AS power_signal,CASE WHEN t.min_link_avail<99 THEN 1 ELSE 0 END AS transport_signal FROM fault__alarm a LEFT JOIN e ON a.station_id=e.station_id AND REPLACE(SUBSTR(a.opened_at,1,13),' ','-')=e.date_hour LEFT JOIN t ON a.station_id=t.station_id AND REPLACE(SUBSTR(a.opened_at,1,13),' ','-')=t.date_hour ORDER BY a.alarm_id","temporal_join","root_cause","multi_cte")
add("extreme","Với từng khiếu nại, nối ticket, công việc và lượt kỹ thuật viên đến trạm; tính thời điểm đóng xử lý.","SELECT c.complaint_id,c.customer_id,c.opened_at,c.closed_at,t.ticket_id,t.resolved_at,w.work_order_id,w.actual_end,v.arrived_at,v.completed_at FROM experience__complaint c LEFT JOIN ops__ticket t ON c.ticket_id=t.ticket_id LEFT JOIN maintenance__work_order w ON t.ticket_id=w.ticket_id LEFT JOIN ops__technician_visit v ON w.work_order_id=v.work_order_id ORDER BY c.complaint_id","multi_join","customer","timeline")
add("extreme","Theo tỉnh, so doanh thu hóa đơn với chi phí điện đã ghi nhận, rồi xếp hạng tỷ lệ chi phí điện trên doanh thu.","WITH b AS (SELECT province_code,SUM(total_vnd) AS billed_vnd FROM billing__invoice GROUP BY province_code),e AS (SELECT province_code,SUM(cost_vnd) AS energy_cost_vnd FROM energy__station_hourly GROUP BY province_code),x AS (SELECT b.province_code,b.billed_vnd,e.energy_cost_vnd,ROUND(100.0*e.energy_cost_vnd/NULLIF(b.billed_vnd,0),2) AS energy_to_bill_pct FROM b JOIN e ON b.province_code=e.province_code) SELECT x.*,DENSE_RANK() OVER(ORDER BY energy_to_bill_pct DESC) AS cost_rank FROM x ORDER BY cost_rank,province_code","multi_cte","finance","window")
add("extreme","Dự báo trạm nào rủi ro từ trung bình trở lên trong khi mức sử dụng PRB thực tế thấp hơn trung bình toàn mạng?","WITH a AS (SELECT station_id,AVG(prb_dl_util_pct) AS avg_prb FROM ran_kpi__cell_hourly GROUP BY station_id),n AS (SELECT AVG(prb_dl_util_pct) AS network_prb FROM ran_kpi__cell_hourly) SELECT f.station_id,f.forecast_date,f.projected_util_pct,ROUND(a.avg_prb,2) AS actual_avg_prb,ROUND(n.network_prb,2) AS network_avg_prb FROM capacity__forecast_daily f JOIN a ON f.station_id=a.station_id CROSS JOIN n WHERE f.risk_level IN ('medium','high') AND a.avg_prb<n.network_prb ORDER BY f.projected_util_pct DESC,f.station_id","forecast","multi_cte","anomaly")
add("extreme","Tính chi phí điện trên mỗi GB tải xuống theo tỉnh từng ngày, tránh nhân bản dòng giữa hai bảng giờ.","WITH e AS (SELECT province_code,SUBSTR(date_hour,1,10) AS day,SUM(cost_vnd) AS cost_vnd FROM energy__station_hourly GROUP BY province_code,SUBSTR(date_hour,1,10)),r AS (SELECT province_code,SUBSTR(date_hour,1,10) AS day,SUM(dl_traffic_gb) AS dl_gb FROM ran_kpi__cell_hourly GROUP BY province_code,SUBSTR(date_hour,1,10)) SELECT e.province_code,e.day,e.cost_vnd,ROUND(r.dl_gb,2) AS dl_gb,ROUND(e.cost_vnd/NULLIF(r.dl_gb,0),2) AS vnd_per_gb FROM e JOIN r ON e.province_code=r.province_code AND e.day=r.day ORDER BY vnd_per_gb DESC,e.province_code,e.day","multi_cte","ratio","energy")
add("extreme","Khách hàng nợ tiền ở trạm có cell chất lượng suy giảm: tổng nợ và số giờ cell suy giảm theo khách hàng.","WITH d AS (SELECT customer_id,SUM(total_vnd-paid_vnd) AS debt_vnd FROM billing__invoice GROUP BY customer_id HAVING SUM(total_vnd-paid_vnd)>0),r AS (SELECT station_id,COUNT(*) AS degraded_hours FROM ran_kpi__cell_hourly WHERE kpi_quality_flag='degraded' GROUP BY station_id) SELECT s.customer_id,s.station_id,d.debt_vnd,r.degraded_hours FROM service__subscription s JOIN d ON s.customer_id=d.customer_id JOIN r ON s.station_id=r.station_id ORDER BY r.degraded_hours DESC,d.debt_vnd DESC,s.customer_id","multi_cte","customer","network")
add("extreme","Theo gói cước, so giá mỗi Mbps cam kết với thông lượng thực đo ở trạm thuê bao và xếp hạng chênh lệch.","WITH r AS (SELECT station_id,AVG(dl_throughput_mbps) AS measured_mbps FROM ran_kpi__cell_hourly GROUP BY station_id),x AS (SELECT p.plan_id,p.plan_name,p.monthly_fee_vnd,p.down_mbps,AVG(r.measured_mbps) AS observed_mbps FROM product__plan p JOIN service__subscription s ON p.plan_id=s.plan_id JOIN r ON s.station_id=r.station_id GROUP BY p.plan_id,p.plan_name,p.monthly_fee_vnd,p.down_mbps) SELECT plan_name,ROUND(1.0*monthly_fee_vnd/NULLIF(down_mbps,0),2) AS vnd_per_advertised_mbps,ROUND(observed_mbps,2) AS observed_mbps,ROUND(observed_mbps/NULLIF(down_mbps,0),2) AS observed_to_advertised FROM x ORDER BY observed_to_advertised,plan_name","multi_cte","product","ratio")
add("extreme","Tính chi phí điện lũy kế từng tỉnh qua các ngày, cùng thứ hạng chi phí lũy kế trong ngày.","WITH d AS (SELECT province_code,SUBSTR(date_hour,1,10) AS day,SUM(cost_vnd) AS daily_vnd FROM energy__station_hourly GROUP BY province_code,SUBSTR(date_hour,1,10)),c AS (SELECT d.*,SUM(daily_vnd) OVER(PARTITION BY province_code ORDER BY day ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_vnd FROM d) SELECT c.*,DENSE_RANK() OVER(PARTITION BY day ORDER BY cumulative_vnd DESC) AS day_rank FROM c ORDER BY day,day_rank,province_code","window","finance","time")
add("extreme","So KPI nguồn bad cell của AAM với số giờ cell suy giảm trong dữ liệu tổng hợp theo từng tỉnh.","WITH a AS (SELECT province_code,SUM(kpi_value) AS source_bad_cells FROM aam__kpi_aam_daily_tdxl WHERE location_level='province' AND kpi_code='bad_cell_throughput_5g' GROUP BY province_code),r AS (SELECT province_code,COUNT(*) AS degraded_hours FROM ran_kpi__cell_hourly WHERE kpi_quality_flag='degraded' GROUP BY province_code) SELECT a.province_code,a.source_bad_cells,COALESCE(r.degraded_hours,0) AS synthetic_degraded_hours FROM a LEFT JOIN r ON a.province_code=r.province_code ORDER BY a.province_code","source","multi_cte","comparison")
add("extreme","Tỉnh nào có cell trong bảng cấu hình nhưng không có phép đo giờ, và tỷ lệ phủ phép đo là bao nhiêu?","WITH c AS (SELECT province_code,COUNT(*) AS configured_cells FROM ran__cell GROUP BY province_code),m AS (SELECT province_code,COUNT(DISTINCT cell_id) AS measured_cells FROM ran_kpi__cell_hourly GROUP BY province_code) SELECT c.province_code,c.configured_cells,COALESCE(m.measured_cells,0) AS measured_cells,ROUND(100.0*COALESCE(m.measured_cells,0)/NULLIF(c.configured_cells,0),2) AS coverage_pct FROM c LEFT JOIN m ON c.province_code=m.province_code ORDER BY coverage_pct,c.province_code","coverage","multi_cte","quality")
add("extreme","Kiểm tra tổng bộ đếm request, accept, reject trong bản ghi xác thực AAA và đếm sai lệch theo tỉnh.","WITH x AS (SELECT province_code,auth_id,request_count,accept_count,reject_count,CASE WHEN request_count<>accept_count+reject_count THEN 1 ELSE 0 END AS mismatch FROM aaa__authentication) SELECT province_code,COUNT(*) AS records,SUM(mismatch) AS mismatch_records,SUM(request_count) AS requests,SUM(accept_count) AS accepts,SUM(reject_count) AS rejects FROM x GROUP BY province_code ORDER BY mismatch_records DESC,province_code","source","quality","aggregate")
add("extreme","Lấy bản ghi Wi-Fi và uptime mới nhất của mỗi thiết bị, rồi xếp hạng thiết bị có retry Wi-Fi cao.","WITH w AS (SELECT device_id,record_time,retry_rate,client_count,ROW_NUMBER() OVER(PARTITION BY device_id ORDER BY record_time DESC,wifi_id DESC) AS rn FROM acs__f_wifi),u AS (SELECT device_id,record_time,uptime_s,ROW_NUMBER() OVER(PARTITION BY device_id ORDER BY record_time DESC,uptime_id DESC) AS rn FROM acs__f_uptime) SELECT d.device_id,d.manufacturer,w.record_time AS wifi_time,w.retry_rate,w.client_count,u.uptime_s FROM acs__device_info d JOIN w ON d.device_id=w.device_id AND w.rn=1 JOIN u ON d.device_id=u.device_id AND u.rn=1 ORDER BY w.retry_rate DESC,d.device_id LIMIT 10","source","window","acs")
add("extreme","Đối chiếu KPI AAM theo cấp tỉnh với tổng các bản ghi cùng mã KPI ở cấp khu vực.","WITH p AS (SELECT area_code,kpi_code,SUM(kpi_value) AS province_total FROM aam__kpi_aam_daily_tdxl WHERE location_level='province' GROUP BY area_code,kpi_code),a AS (SELECT area_code,kpi_code,SUM(kpi_value) AS area_total FROM aam__kpi_aam_daily_tdxl WHERE location_level='area' GROUP BY area_code,kpi_code) SELECT p.area_code,p.kpi_code,p.province_total,a.area_total,p.province_total-a.area_total AS gap FROM p JOIN a ON p.area_code=a.area_code AND p.kpi_code=a.kpi_code ORDER BY ABS(gap) DESC,p.area_code,p.kpi_code","source","multi_cte","reconciliation")
add("extreme","Xếp hạng tỉnh theo điểm rủi ro tổng hợp từ khả dụng cell, tỷ lệ QoS thành công, khiếu nại và hóa đơn nợ.","WITH r AS (SELECT province_code,AVG(availability_pct) AS avail FROM ran_kpi__cell_hourly GROUP BY province_code),q AS (SELECT province_code,100.0*SUM(success_count)/NULLIF(SUM(request_count),0) AS qos_pct FROM qos__service_hourly GROUP BY province_code),c AS (SELECT province_code,COUNT(*) AS subscribers FROM customer__subscriber GROUP BY province_code),x AS (SELECT province_code,COUNT(*) AS complaints FROM experience__complaint GROUP BY province_code),b AS (SELECT province_code,100.0*SUM(CASE WHEN paid_vnd<total_vnd THEN 1 ELSE 0 END)/NULLIF(COUNT(*),0) AS unpaid_pct FROM billing__invoice GROUP BY province_code),s AS (SELECT r.province_code,ROUND((100-r.avail)+(100-q.qos_pct)+100.0*COALESCE(x.complaints,0)/NULLIF(c.subscribers,0)+b.unpaid_pct,2) AS risk_score FROM r JOIN q ON r.province_code=q.province_code JOIN c ON r.province_code=c.province_code LEFT JOIN x ON r.province_code=x.province_code JOIN b ON r.province_code=b.province_code) SELECT s.*,DENSE_RANK() OVER(ORDER BY risk_score DESC) AS risk_rank FROM s ORDER BY risk_rank,province_code","multi_cte","composite","ranking")
